using BenchmarkDotNet.Attributes;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using OptimizingEfCoreQueries.Shared;
using OptimizingEfCoreQueries.Solutions;

namespace OptimizingEfCoreQueries.Benchmarks;

// Baseline holds the original N+1 implementation (never edited); Optimized calls
// the agent-owned NPlusOneSolution.Run. Do not edit this file — edit
// Solutions/NPlusOne.cs.
[Config(typeof(SharedBenchmarkConfig))]
public class NPlusOneBenchmark
{
    private SqliteConnection _connection = null!;

    [GlobalSetup]
    public void Setup()
    {
        _connection = AppDbContext.OpenSharedConnection();
        using var db = AppDbContext.Create(_connection);
        db.Database.EnsureCreated();
        SeedData.SeedCustomersWithOrders(db, customers: 300, ordersPerCustomer: 20);

        EquivalenceGuard.SameResults(Baseline(), Optimized(), s => s.Name);
    }

    [GlobalCleanup]
    public void Cleanup() => _connection.Dispose();

    [Benchmark(Baseline = true)]
    public List<CustomerOrderSummary> Baseline()
    {
        using var db = AppDbContext.Create(_connection);
        var customers = db.Customers.ToList();
        var summaries = new List<CustomerOrderSummary>();
        foreach (var customer in customers)
        {
            var orders = db.Orders.Where(o => o.CustomerId == customer.Id).ToList();
            summaries.Add(new CustomerOrderSummary(customer.Name, orders.Count, orders.Sum(o => o.Total)));
        }

        return summaries;
    }

    [Benchmark]
    public List<CustomerOrderSummary> Optimized()
    {
        using var db = AppDbContext.Create(_connection);
        return NPlusOneSolution.Run(db);
    }
}
